import { CandlestickChart, useCandlestickChart } from '@dreadnought/ui/react';
const data = [{id:'a',label:'Пн',open:100,high:120,low:90,close:110}];
function Summary() { const {candles,page} = useCandlestickChart(); return <p>{candles.length} периодов; страница {page.page}</p>; }
export function Example() { return <CandlestickChart data={data} label="Котировки"><Summary /><CandlestickChart.Plot height={180} tooltipContent={({defaultContent}) => <div>OHLC{defaultContent}</div>}>{({defaultContent}) => defaultContent}</CandlestickChart.Plot><CandlestickChart.Empty /><CandlestickChart.Table /><CandlestickChart.Pagination /></CandlestickChart>; }

import { CandlestickChart } from '@dreadnought/ui/react';
const data = [{ id: 'a', label: 'Пн', open: 100, high: 114, low: 96, close: 110 }, { id: 'b', label: 'Вт', open: 110, high: 117, low: 99, close: 103 }];
export function Example() { return <CandlestickChart label="Котировки" data={data} formatValue={value => value.toFixed(2)} />; }
